{"filePath":"/tmp/opencode/localpypi/server.py","content":""""Minimal PyPI-compatible upload server for local testing."""
import cgi
import os
import sys
from http.server import HTTPServer, BaseHTTPRequestHandler

PACKAGE_DIR = os.path.join(os.path.dirname(__file__), "packages")
os.makedirs(PACKAGE_DIR, exist_ok=True)


class PyPIHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"Local PyPI")

    def do_POST(self):
        content_type = self.headers.get("Content-Type", "")
        content_length = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(content_length)
        if "multipart/form-data" in content_type:
            boundary = content_type.split("boundary=")[1].encode()
            filename = self._extract_filename(body, boundary)
            if filename:
                file_data = self._extract_file(body, boundary, filename)
                dest = os.path.join(PACKAGE_DIR, filename)
                with open(dest, "wb") as f:
                    f.write(file_data)
                print(f"Uploaded: {filename} ({len(file_data)} bytes)")
                self.send_response(200)
                self.end_headers()
                return
        self.send_response(200)
        self.end_headers()

    def _parse_multipart(self, body, boundary):
        parts = []
        sep = b"--" + boundary
        chunks = body.split(sep)
        for chunk in chunks:
            if chunk.strip() in (b"", b"--"):
                continue
            if b"\r\n\r\n" in chunk:
                header, data = chunk.split(b"\r\n\r\n", 1)
                if data.endswith(b"\r\n"):
                    data = data[:-2]
                parts.append((header.decode("utf-8", errors="replace"), data))
        return parts

    def _extract_filename(self, body, boundary):
        parts = self._parse_multipart(body, boundary)
        for header, _ in parts:
            if 'name="content"' in header or 'name="file"' in header:
                if "filename=" in header:
                    fn = header.split("filename=")[1].split('"')[1]
                    return fn
        return None

    def _extract_file(self, body, boundary, filename):
        parts = self._parse_multipart(body, boundary)
        for header, data in parts:
            if filename in header:
                return data
        return b""


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8765
    server = HTTPServer(("127.0.0.1", port), PyPIHandler)
    print(f"Local PyPI server on http://127.0.0.1:{port}")
    server.serve_forever()
